function formatMoney(cents) {
  const sign = cents < 0 ? '-' : '';
  const abs = Math.abs(cents);
  return `${sign}$${Math.floor(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
}

function renderBalances(container, balances) {
  const names = Object.keys(balances).sort((a, b) => a.localeCompare(b));
  if (names.length === 0) {
    const empty = document.createElement('p');
    empty.textContent = 'No expenses yet';
    container.replaceChildren(empty);
    return;
  }
  const list = document.createElement('ul');
  list.setAttribute('aria-label', 'Balances');
  for (const name of names) {
    const cents = balances[name];
    const item = document.createElement('li');
    item.textContent =
      cents > 0 ? `${name} is owed ${formatMoney(cents)}`
      : cents < 0 ? `${name} owes ${formatMoney(-cents)}`
      : `${name} is settled up`;
    list.append(item);
  }
  container.replaceChildren(list);
}

// Shows balances loaded with loadBalances() (returns a promise).
// - While loading: <p role="status">Loading balances…</p>
// - On success: the "Balances" list from renderBalances; the status is gone.
// - On failure: <p role="alert">Could not load balances.</p> and a
//   "Try again" button that calls loadBalances again.
function mountBalancePanel(container, loadBalances) {
  async function load() {
    container.innerHTML = '<p role="status">Loading balances…</p>';
    try {
      const balances = await loadBalances();
      renderBalances(container, balances);
    } catch {
      container.innerHTML =
        '<p role="alert">Could not load balances.</p><button type="button">Try again</button>';
      container.querySelector('button').addEventListener('click', load);
    }
  }
  load();
}

